static const unsigned int font_shadow_len = 13365;

typedef struct { const char *name; const unsigned char *data; unsigned int len; } embedded_font_t;

static const embedded_font_t embedded_fonts[] = {
  { "standard", font_standard, 28521 },
  { "small", font_small, 12235 },
  { "slant", font_slant, 15520 },
  { "big", font_big, 26384 },
  { "shadow", font_shadow, 13365 },
  { NULL, NULL, 0 }
};

/* Returns a FILE* reading from embedded font data, or NULL if not found */
static FILE *open_embedded_font(const char *name) {
  const embedded_font_t *f;
  for (f = embedded_fonts; f->name != NULL; f++) {
    if (strcmp(f->name, name) == 0)
      return fmemopen((void*)f->data, f->len, "rb");
  }
  return NULL;
}
